function makeCollection(id, name, prefix, counts, opts={}) {
  const records = counts.map((count,i) => ({
    id:`src-${id}-${String(i+1).padStart(3,'0')}`, name:`${prefix}_${String(i+1).padStart(3,'0')}.wav`,
    path:`recordings/${prefix}_${String(i+1).padStart(3,'0')}.wav`, seconds: 540 + (i*73)%370,
    sampleRate:48000, channels:1, positives:count, aligned: !opts.invalid, bytes:Math.round((540+(i*73)%370)*96000)
  }));
  const positives=records.flatMap((r,i)=>Array.from({length:r.positives},(_,j)=>{const start=12000+(j*17300)+(i*200);return {name:`${prefix}_${String(i+1).padStart(3,'0')}__start-${String(start).padStart(6,'0')}ms__end-${String(start+2400).padStart(6,'0')}ms__call${String(j+1).padStart(2,'0')}.wav`,sourceId:r.id,startMs:start,endMs:start+2400};}));
  return {id,name,positives,root:`~/Research/${name.toLowerCase().replaceAll(' ','-')}`,records,
    positiveFiles:counts.reduce((a,c)=>a+c,0), extraFiles:opts.invalid?1:0,
    issues:opts.invalid?[
      {code:'MISSING_SOURCE',title:'Unknown recording prefix',detail:'positives/OTHER_006__start-010000ms__end-012400ms__call01.wav does not identify any WAV in recordings/.'},
      {code:'NOT_WAV',title:'Only WAV files are accepted',detail:'positives/notes.mp3 is not a WAV file.'},
      {code:'TIMING',title:'Missing source timestamps',detail:'positives/UNMAPPED_001__call03.wav needs __start-…ms__end-…ms in its name.'}
    ]:[], demo:true, verified:!opts.invalid, lastChecked:today, cacheStatus:'ready',
    annotationSource:opts.invalid?'partial':'filename times checked against WAV headers (mock)'};
}
