function home(){page(`<div class="narrow"><div class="hero center"><div class="eyebrow">COLLECTION → DATASET → MODEL</div><h1>Train from a collection</h1><p>Choose a local folder of WAV recordings and labeled positive snippets.</p></div><section class="panel panel-inner"><div class="section-title"><div><h2>Select Collection</h2><p>We check the folder. No import or audio copy.</p></div>${tip('A Collection is the folder you already have. It includes recordings/ and positives/. Each positive WAV filename identifies its source and exact start/end in milliseconds.',true)}</div><div class="choose-box"><div class="choose-icon">${ico('folder',20)}</div><strong>One folder, two subfolders</strong><p class="mono">recordings/ &nbsp; + &nbsp; positives/</p><button class="btn primary" onclick="chooseFolder()">${ico('folder',15)} Select folder</button><a class="subtle-link" href="#/wiki">How should my folder look? →</a><small>Local only · WAV headers are read in small chunks.</small></div><div class="subsection-line"><h3>Explore with sample data</h3><small>Mock collections</small></div><div class="sample-grid">${state.collections.filter(c=>c.demo).map(c=>`<button class="sample-card" onclick="scanSample('${c.id}')"><div class="sample-top">${ico('folder',18)}<span class="sample-tag ${c.issues.length?'warning':''}">${c.issues.length?'Has issues':'Valid example'}</span></div><h4>${esc(c.name)}</h4><p>${c.records.length} recordings · ${c.positiveFiles} positives</p></button>`).join('')}</div></section><div class="footnote">Interactive demonstration · mock Training and Dataset Builds · selecting a real folder only validates headers and names</div></div>`,'Select Collection')}
function chooseFolder(){const input=$('folder-input');input.value='';input.click()}
