function showScan(){const sc=state.scan;if(!sc)return go('start');page(`<div class="narrow"><div class="hero"><div class="eyebrow">SELECT COLLECTION</div><h1>Reading ${esc(sc.name)}</h1><p>Validating filenames, timestamps, and WAV headers…</p></div><div class="panel panel-inner"><div class="section-title"><h2>${esc(sc.stage)}</h2>${badge('Local scan','warn')}</div><div class="progress-head"><strong>${fmt(sc.done)} / ${fmt(sc.total)} files</strong><strong>${sc.total?Math.round(100*sc.done/sc.total):0}%</strong></div><div class="bar" role="progressbar" aria-valuenow="${sc.total?Math.round(100*sc.done/sc.total):0}" aria-valuemin="0" aria-valuemax="100"><span style="width:${sc.total?100*sc.done/sc.total:0}%"></span></div><div class="kv"><span>Recordings inspected</span><b>${fmt(sc.recordings)}</b></div><div class="kv"><span>Positives inspected</span><b>${fmt(sc.positives)}</b></div><div class="kv"><span>Issues so far</span><b>${fmt(sc.issues)}</b></div><div class="action-strip"><span class="subtle">You can cancel this scan.</span><button class="btn" onclick="cancelScan()">Cancel scan</button></div></div><div class="footnote">Browsing large folders will use a nonblocking native I/O worker. This browser demonstration yields between batches.</div></div>`,'Reading Collection')}
function cancelScan(){scanToken++;state.scan=null;go('start')}
function updateScan(stage,done,recordings,positives,issues){const sc=state.scan;if(!sc)return;Object.assign(sc,{stage,done,recordings,positives,issues});if(getRoute()==='scan')showScan()}
function scanSample(id){const c=coll(id);if(!c)return;const token=++scanToken;state.scan={name:c.name,stage:'Listing files',total:c.records.length+c.positiveFiles,done:0,recordings:0,positives:0,issues:0};go('scan');let step=0;const span=setInterval(()=>{if(token!==scanToken){clearInterval(span);return;}step++;const n=Math.min(state.scan.total,Math.ceil(step*state.scan.total/10));updateScan(step<6?'Inspecting WAV headers':'Checking timestamps',n,Math.min(c.records.length,n),Math.max(0,n-c.records.length),step>=8?c.issues.length:0);if(step>=10){clearInterval(span);state.scan=null;openCollection(id)}},125)}
// Header-only browser preview. This is not full decoding or waveform-content verification.
async function readWavHeader(file){
 const buf=await file.slice(0,65536).arrayBuffer(),d=new DataView(buf);
 const txt=(i,n)=>Array.from({length:n},(_,j)=>String.fromCharCode(d.getUint8(i+j))).join('');
 if(d.byteLength<44||txt(0,4)!=='RIFF'||txt(8,4)!=='WAVE')throw Error('Not a supported RIFF/WAVE header');
 let offset=12,fmt=null,bytes=null;
 while(offset+8<=d.byteLength){const tag=txt(offset,4),size=d.getUint32(offset+4,true),body=offset+8;
   if(tag==='fmt '&&size>=16&&body+16<=d.byteLength){const type=d.getUint16(body,true),channels=d.getUint16(body+2,true),rate=d.getUint32(body+4,true),align=d.getUint16(body+12,true),bits=d.getUint16(body+14,true);fmt={type,channels,rate,align,bits};}
   if(tag==='data'){bytes=size;break;}if(size>65536||body+size>d.byteLength)break;offset=body+size+(size%2);
 }
 if(!fmt||bytes===null)throw Error('WAV fmt/data chunks not available in the header preview');
 if(![1,3].includes(fmt.type)||![1,2].includes(fmt.channels)||fmt.rate<=0||fmt.align<=0||fmt.bits<=0)throw Error('Unsupported WAV encoding or channels');
 if(bytes%fmt.align!==0||bytes<=0)throw Error('Invalid or empty WAV audio data');
 if(bytes>file.size)throw Error('WAV data size exceeds file size');
 const frames=bytes/fmt.align;return {channels:fmt.channels,sampleRate:fmt.rate,seconds:frames/fmt.rate,frames,bytes:file.size};
}
const baseOf=name=>name.replace(/\.wav$/i,'');
const keyOf=name=>name.normalize('NFC').toLowerCase();
const timeName=/^(.*?)__start-(\d{1,12})ms__end-(\d{1,12})ms__(.+)$/i;
function validateCollectionFiles(files,root){
 const records=[],positives=[],issues=[],other=[];
 const report=(code,title,detail)=>issues.push({code,title,detail});
 let roots=new Set();let allNames=new Set();
 for(const f of files){const relative=f.relative;const parts=relative.split('/');roots.add(parts[0]);
  if(parts.length!==2||!['recordings','positives'].includes(parts[0])){if(relative.startsWith('.alpaca/'))continue;other.push(relative);report('LAYOUT','Unexpected path',`${relative} — place WAV files directly in recordings/ or positives/.`);continue;}
  if(!/\.wav$/i.test(f.file.name)){report('EXT','Only WAV files are allowed',`${relative} — remove or convert this file.`);continue;}
  const identity=keyOf(relative);if(allNames.has(identity))report('COLLISION','Filename collision',`${relative} conflicts with another name after case/Unicode normalization.`);allNames.add(identity);
  const item={id:uid(parts[0]==='recordings'?'src':'pos'),name:f.file.name,path:relative,bytes:f.file.size,seconds:f.info?.seconds??0,sampleRate:f.info?.sampleRate??0,channels:f.info?.channels??0,frames:f.info?.frames??0,lastModified:f.file.lastModified,positives:0,aligned:false};
  if(!f.info)report('WAV','Invalid or unsupported WAV',`${relative}: ${f.error||'Cannot read header.'}`);
  (parts[0]==='recordings'?records:positives).push(item);
 }
 if(!roots.has('recordings'))report('MISSING_FOLDER','Missing recordings/','Add a recordings/ subfolder with full-length WAVs.');
 if(!roots.has('positives'))report('MISSING_FOLDER','Missing positives/','Add a positives/ subfolder with positive WAV snippets.');
 if(!records.length)report('EMPTY_RECORDINGS','No recordings found','Add at least one valid WAV under recordings/.');
 if(!positives.length)report('EMPTY_POSITIVES','No positives found','Add at least one positive WAV under positives/.');
 const names=new Map();records.forEach(r=>{const k=keyOf(baseOf(r.name));if(names.has(k))report('COLLISION','Ambiguous Source Recording names',`${r.name} and ${names.get(k).name} differ only by case/Unicode.`);else names.set(k,r);});
 const spans=new Set();
 positives.forEach(p=>{
  const match=baseOf(p.name).match(timeName);
  if(!match){report('NAME','Positive has no timestamps',`${p.path}: use RECORDING__start-012500ms__end-014900ms__call01.wav.`);return;}
  const source=names.get(keyOf(match[1]));if(!source){report('SOURCE','Unknown Source Recording',`${p.path}: “${match[1]}.wav” was not found under recordings/.`);return;}
  const a=Number(match[2]),b=Number(match[3]);
  if(!match[4].trim()||!Number.isSafeInteger(a)||!Number.isSafeInteger(b)||a<0||b<=a){report('TIME','Invalid time interval',`${p.path}: start must be nonnegative and end must be later than start.`);return;}
  if(!source.seconds||b>Math.round(source.seconds*1000)+2){report('BOUNDS','Snippet outside recording',`${p.path}: end at ${(b/1000).toFixed(3)} s exceeds source duration ${source.seconds.toFixed(3)} s.`);return;}
  if(!p.seconds||Math.abs((b-a)/1000-p.seconds)>0.015){report('DURATION','Snippet duration disagrees with filename',`${p.path}: filename says ${((b-a)/1000).toFixed(3)} s; WAV header says ${p.seconds.toFixed(3)} s.`);return;}
  const span=`${source.id}:${a}:${b}`;if(spans.has(span)){report('DUPLICATE_SPAN','Duplicate positive interval',`${p.path}: source interval already has an example.`);return;}spans.add(span);
  p.startMs=a;p.endMs=b;p.sourceId=source.id;source.positives++;p.aligned=true;
 });
 return {id:uid('c'),name:root,root:`Selected folder: ${root}`,records,positives,positiveFiles:positives.length,extraFiles:other.length,issues,demo:false,verified:issues.length===0,lastChecked:today,cacheStatus:'session only',annotationSource:'filename timestamp + WAV-header consistency (not waveform identity)'};
}
async function inspectLocal(input){
 const list=[...input.files];if(!list.length)return;
 const root=(list[0].webkitRelativePath||list[0].name).split('/')[0],token=++scanToken;
 state.scan={name:root,stage:'Listing folder',total:list.length,done:0,recordings:0,positives:0,issues:0};go('scan');
 await pause();if(token!==scanToken)return;
 const files=[];let rec=0,pos=0,errors=0;
 for(let start=0;start<list.length;start+=16){
  if(token!==scanToken)return;
  const batch=list.slice(start,start+16);
  const results=await Promise.all(batch.map(async file=>{
    const relative=(file.webkitRelativePath||file.name).split('/').slice(1).join('/');
    if(!relative||relative.startsWith('.alpaca/'))return {file,relative,info:null};
    if(!/^(recordings|positives)\/[^/]+\.wav$/i.test(relative))return {file,relative,info:null};
    try{return {file,relative,info:await readWavHeader(file)}}catch(e){return {file,relative,info:null,error:e.message}};
  }));
  for(const f of results){if(f.relative){files.push(f);rec+=f.relative.startsWith('recordings/')?1:0;pos+=f.relative.startsWith('positives/')?1:0;errors+=f.error?1:0;}}
  updateScan('Reading WAV headers',Math.min(list.length,start+batch.length),rec,pos,errors);
  await pause();
 }
 if(token!==scanToken)return;updateScan('Checking filenames and timestamps',list.length,rec,pos,errors);await pause();
 const collection=validateCollectionFiles(files,root);state.scan=null;state.collections.unshift(collection);openCollection(collection.id);
}
$('folder-input').addEventListener('change',e=>inspectLocal(e.target).catch(err=>{state.scan=null;notify('Folder validation failed: '+err.message);go('start')}));
function collectionsPage(){page(`<div class="wide">${heading('DATA','Collections','Your selected local folders.',`<button class="btn primary" onclick="go('start')">${ico('plus',14)} Select Collection</button>`)}<div class="panel table-wrap"><table class="data-table"><thead><tr><th>Collection</th><th>Recordings</th><th>Positives</th><th>Checks</th><th></th></tr></thead><tbody>${state.collections.map(c=>`<tr class="clickable" onclick="openCollection('${c.id}')"><td><strong>${esc(c.name)}</strong><small class="mono">${esc(c.id)}</small></td><td>${fmt(c.records.length)}</td><td>${fmt(c.positiveFiles)}</td><td>${c.verified?badge('Valid','success'):badge(`${c.issues.length} issues`,'warn')}</td><td class="table-link">Open →</td></tr>`).join('')}</tbody></table></div><div class="footnote">The selected folder is the Collection. Source WAVs remain where they are.</div></div>`,'Collections')}
function collectionPage(id){const c=coll(id);if(!c)return notFound();state.selectedCollection=c.id;
 const actions=`<button class="btn" onclick="downloadCollectionManifest('${c.id}')">${ico('download',14)} Preview manifest JSON</button> ${c.verified?`<button class="btn primary" onclick="startBuild('${c.id}')">Build Dataset ${ico('arrow',14)}</button>`:`<button class="btn" onclick="go('start')">Choose another folder</button>`}`;
 const alert=c.verified?`<div class="alert">${ico('check',17)}<div><strong>Collection valid</strong><p>Folder, WAV headers, source names and snippet timestamps are consistent.</p></div></div>`:`<div class="alert warning">${ico('shield',17)}<div><strong>${c.issues.length} validation ${c.issues.length===1?'issue':'issues'}</strong><p>Fix the files listed below, then select the folder again. Dataset Build is unavailable.</p></div></div>`;
 const sample=c.positives?.find(p=>p.startMs!=null)||c.positives?.[0];
 page(`<div class="wide">${bread('Collections','collections',c.name)}${heading('COLLECTION',c.name,esc(c.root),actions)}${stats([['Source Recordings',fmt(c.records.length),'Original WAVs'],['Positive examples',fmt(c.positiveFiles),'Labeled WAVs'],['Recorded audio',statDuration(totalDuration(c)),'From WAV headers'],['Collection',c.verified?'Valid':'Needs fixes',c.demo?'Mock validation':'Browser header checks']])}${alert}<div class="two-col" style="margin-top:17px"><div class="stack"><div class="panel"><div class="panel-inner" style="padding-bottom:8px"><div class="section-title"><div><h2>Recordings</h2><p>Positive snippets by Source Recording</p></div>${tip('Positive WAV names reference the entire Source Recording name and carry start/end timestamps in milliseconds.',true)}</div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Source Recording</th><th>Length</th><th>Positives</th></tr></thead><tbody>${c.records.slice(0,30).map(r=>`<tr><td><strong class="mono">${esc(r.name)}</strong></td><td>${r.seconds?(r.seconds/60).toFixed(1)+' min':'—'}</td><td>${r.positives}</td></tr>`).join('')}</tbody></table>${c.records.length>30?`<p class="subtle" style="padding:0 18px">Showing 30 of ${fmt(c.records.length)} (demo pagination).</p>`:''}</div></div><div class="panel panel-inner"><div class="section-title"><h2>Validation details</h2><a class="subtle-link" href="#/wiki">Naming guide →</a></div>${c.issues.length?`<div class="issues">${c.issues.slice(0,40).map(i=>`<div class="issue error"><strong>${esc(i.title)}</strong><small>${esc(i.detail)}</small></div>`).join('')}</div>${c.issues.length>40?`<p class="subtle">Showing 40 of ${c.issues.length} issues</p>`:''}`:`<div class="kv"><span>Folders and WAV headers</span>${badge('Passed','success')}</div><div class="kv"><span>Recording names</span>${badge('Passed','success')}</div><div class="kv"><span>Timestamp bounds / duration</span>${badge('Passed','success')}</div><div class="kv"><span>Last checked</span><b>${esc(c.lastChecked)}</b></div>`}</div></div><div class="stack"><div class="panel panel-inner"><div class="section-title"><h2>Folder</h2>${tip('There is no app-specific ingest format. The native Trainer will write compact, refreshable metadata under .alpaca/ without changing source WAV files.',true)}</div><div class="tree"><div>${ico('folder',12)} ${esc(c.name)}/</div><div class="level1">├─ <em>recordings/</em> <span class="light">${fmt(c.records.length)} WAV</span></div><div class="level2">${esc(c.records[0]?.name||'recording.wav')}</div><div class="level1">├─ <em>positives/</em> <span class="light">${fmt(c.positiveFiles)} WAV</span></div><div class="level2">${esc(sample?.name||'recording__start-…ms__end-…ms__call01.wav')}</div><div class="level1">└─ <em>.alpaca/</em> <span class="light">proposed generated metadata + outputs</span></div><div class="level2">collection.json · datasets/ · models/ · runs/</div></div></div><div class="panel panel-inner"><div class="section-title"><h2>Fast reopening</h2>${tip('Native app: persist compact fingerprints, counts and partition references. Reuse unchanged headers; changed files are revalidated. The browser cannot write to your selected folder automatically.',true)}</div><div class="kv"><span>Metadata</span><b>${esc(c.demo?'Mock cache ready':c.cacheStatus)}</b></div><div class="kv"><span>Audio copies</span><b>None</b></div><div class="kv"><span>What we check</span><b>Header + names + times</b></div><p class="subtle">${c.demo?'Example data, not inspected WAV bytes.':'This preview can download a JSON sample; it cannot save beside your WAVs.'}</p><button class="btn" onclick="downloadCollectionManifest('${c.id}')">${ico('download',14)} Download manifest preview</button></div></div></div><div class="footnote">Time intervals are user-supplied via filenames; they are not proof of matching waveform content. Native source checks run before Dataset Build.</div></div>`,'Collection · '+c.name);
}
function downloadCollectionManifest(id){const c=coll(id);if(!c)return;const payload={schema_version:1,collection_id:c.id,label:c.name,metadata_kind:'preview-only',verified_by:c.demo?'mock':'browser-name-and-header',recordings_count:c.records.length,positives_count:c.positiveFiles,issues:c.issues,recordings:c.records.map(r=>({id:r.id,path:r.path,seconds:r.seconds,frame_count:r.frames||null,sample_rate_hz:r.sampleRate,channels:r.channels,size_bytes:r.bytes,last_modified_ms:r.lastModified||null})),positives:(c.positives||[]).map(x=>({path:x.path||`positives/${x.name}`,source_recording_id:x.sourceId,start_ms:x.startMs,end_ms:x.endMs}))};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${c.id}-collection-preview.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);notify('Downloaded a metadata preview (not written into your Collection).')}
function startBuild(id){const c=coll(id);if(!c?.verified){notify('Resolve Collection validation before Dataset Build.');return}state.selectedCollection=id;state.selectedRecords=new Set(c.records.map(r=>r.id));go('build')}
function buildPage(){const c=coll(state.selectedCollection);if(!c)return go('collections');const v=computed();const disabled=!c.verified||!v.pos||state.activeRun;const config=state.config;
page(`<div class="wide">${bread(c.name,`collection/${c.id}`,'Build Dataset')}${heading('DATASET BUILD','Create a training Dataset','Select Source Recordings, then configure Negative Mining.',`<span class="badge">Immutable output</span>`)}<div class="builder-layout"><div class="stack"><div class="panel"><div class="panel-inner" style="padding-bottom:8px"><div class="section-title"><div><h2>1 · Choose positive examples</h2><p>Include or exclude complete Source Recordings.</p></div>${tip('Every selected Source Recording contributes its positive Annotations. Deselecting one excludes its positives and its audio from Negative Mining.',true)}</div><div class="action-strip" style="padding:0 0 13px"><label class="checkbox-line"><input type="checkbox" id="all-records" onchange="toggleAll(this.checked)" ${v.sourceCount===c.records.length?'checked':''}> Select all</label><span class="subtle" id="selection-label">${v.sourceCount} of ${c.records.length} recordings</span></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th style="width:38px"></th><th>Source Recording</th><th>Duration</th><th>Positives</th></tr></thead><tbody>${c.records.map(r=>`<tr class="${state.selectedRecords.has(r.id)?'':'table-faded'}"><td><input type="checkbox" aria-label="Include ${esc(r.name)}" ${state.selectedRecords.has(r.id)?'checked':''} onchange="toggleRecord('${r.id}',this.checked)"></td><td><strong class="mono">${esc(r.name)}</strong></td><td>${Math.round(r.seconds/60)} min</td><td>${r.positives}</td></tr>`).join('')}</tbody></table></div></div><div class="panel panel-inner"><div class="section-title"><h2>3 · Dataset preview</h2>${tip('Numbers are configuration estimates. The native builder must enforce exact source-grouped split assignments and fail explicitly when the requested negative count cannot be mined.',true)}</div><div id="build-summary"></div></div></div><div class="panel panel-inner"><div class="section-title"><div><h2>2 · Negative Mining</h2><p>Sample noise from unlabelled audio.</p></div>${tip('Negative Mining samples background windows, never overlapping known positive or other protected time spans. Seeded sampling is reproducible.',true)}</div><div class="setting-block"><label class="inline-label" for="noise-mode">Negative amount ${tip('Use negatives per positive, or specify a total number of negative snippets.',true)}</label><select id="noise-mode" onchange="setBuild('mode',this.value)"><option value="ratio" ${config.mode==='ratio'?'selected':''}>Per positive</option><option value="absolute" ${config.mode==='absolute'?'selected':''}>Total negatives</option></select><div class="field" style="margin:12px 0 0"><label class="inline-label" for="noise-count">${config.mode==='ratio'?'Negatives per positive':'Total negatives'}</label><input id="noise-count" type="number" min="${config.mode==='ratio'?'0':'0'}" max="${config.mode==='ratio'?'20':'200000'}" step="${config.mode==='ratio'?'0.5':'1'}" value="${config.mode==='ratio'?config.ratio:config.absolute}" onchange="setBuild('${config.mode==='ratio'?'ratio':'absolute'}',this.value)"></div></div><div class="setting-block"><label class="inline-label" for="allocation">By Source Recording ${tip('Proportional: more negatives from recordings with more positives. Even: distribute negative requests as evenly as possible across selected recordings; never use unselected recordings.',true)}</label><select id="allocation" onchange="setBuild('allocation',this.value)"><option value="proportional" ${config.allocation==='proportional'?'selected':''}>Proportional to positives</option><option value="even" ${config.allocation==='even'?'selected':''}>Even across recordings</option></select></div><div class="setting-block"><div class="field-row"><label class="field"><span class="inline-label">Training Split ${tip('Percent of the Dataset allocated to train; the remainder goes to val. Group Source Recordings together to avoid audio leakage.',true)}</span><select onchange="setBuild('split',this.value)"><option value="70" ${config.split===70?'selected':''}>70% train / 30% val</option><option value="80" ${config.split===80?'selected':''}>80% train / 20% val</option><option value="90" ${config.split===90?'selected':''}>90% train / 10% val</option></select></label><label class="field"><span class="inline-label">Seed ${tip('The same selected recordings, input bytes, seed, and parameters must produce the same Dataset.',true)}</span><input type="number" min="0" max="2147483647" step="1" value="${config.seed}" onchange="setBuild('seed',this.value)"></label></div><label class="checkbox-line"><input type="checkbox" ${config.balance?'checked':''} onchange="setBuild('balance',this.checked)"> Keep class ratio across Splits ${tip('Try to preserve the configured target/noise ratio separately in train and val while grouping all snippets from one Source Recording in the same Split. If both constraints cannot be met, explain the conflict before publication.',true)}</label><p class="subtle">Split by Source Recording · no source leakage ${tip('All positives and negatives derived from one Source Recording belong to the same train or val Split. This is always on.',true)}</p></div><div class="setting-block"><label class="inline-label">Positive exclusion margin ${tip('Additional time on each side of known positives where negatives cannot be sampled. All protected Annotations are excluded, including those not selected for target examples.',true)}</label><select onchange="setBuild('margin',this.value)"><option value="0" ${config.margin===0?'selected':''}>None</option><option value="0.25" ${config.margin===0.25?'selected':''}>0.25 s</option><option value="0.5" ${config.margin===0.5?'selected':''}>0.5 s</option><option value="1" ${config.margin===1?'selected':''}>1 s</option></select></div><button id="build-action" class="btn primary large" style="width:100%" onclick="runBuild()" ${disabled?'disabled':''}>${ico('spark',17)} Build Dataset ${ico('arrow',16)}</button><p class="subtle" style="font-size:11px;text-align:center;margin:10px 0 0">${state.activeRun?'Another Run is active.':'Source WAVs will not be modified.'}</p></div></div></div>`,'Build Dataset');refreshBuildSummary();}
function toggleAll(on){const c=coll(state.selectedCollection);state.selectedRecords=new Set(on?c.records.map(r=>r.id):[]);buildPage()}
function toggleRecord(id,on){on?state.selectedRecords.add(id):state.selectedRecords.delete(id);buildPage()}
function setBuild(field,value){if(['seed','split','ratio','absolute','margin'].includes(field)){value=Number(value);if(!Number.isFinite(value))return notify('Enter a valid number.');if(field==='seed')value=Math.max(0,Math.min(2147483647,Math.round(value)));if(field==='split')value=Math.max(70,Math.min(90,value));if(field==='ratio')value=Math.max(0,Math.min(20,value));if(field==='absolute')value=Math.max(0,Math.min(200000,Math.round(value)));if(field==='margin')value=Math.max(0,Math.min(1,value));}state.config[field]=value;if(field==='mode')return buildPage();refreshBuildSummary()}
function refreshBuildSummary(){const container=$('build-summary');if(!container)return;const v=computed();const ratio=v.pos?Math.round(v.neg/v.pos*10)/10:0;
 container.innerHTML=`<div class="summary-box"><div class="summary-nums"><div><strong>${fmt(v.pos)}</strong><br><small>target Snippets</small></div><div><strong>${fmt(v.neg)}</strong><br><small>noise Snippets</small></div><div><strong>${fmt(v.pos+v.neg)}</strong><br><small>total</small></div></div><div class="meter split"><span style="width:${v.pos+v.neg?100*v.pos/(v.pos+v.neg):0}%"></span><span style="width:${v.pos+v.neg?100*v.neg/(v.pos+v.neg):0}%"></span></div></div><div class="kv"><span>Selected Source Recordings</span><b>${v.sourceCount}</b></div><div class="kv"><span>Requested negatives / positive</span><b>${ratio} : 1</b></div><div class="kv"><span>train / val (estimated)</span><b>${v.trainPos+v.trainNeg} / ${v.valPos+v.valNeg}</b></div>${v.sourceCount<2?`<div class="alert warning" style="margin-top:12px">Select at least two Source Recordings for a source-grouped train/val Split.</div>`:''}<p class="subtle" style="margin:12px 0 0;font-size:11px">Exact Split membership and underfill checks happen during Dataset Build.</p>`;
 const button=$('build-action');if(button)button.disabled=!v.c.verified||v.sourceCount<2||!v.pos||!v.neg||!!state.activeRun;
 const all=$('all-records');if(all){all.checked=v.sourceCount===v.c.records.length;all.indeterminate=v.sourceCount>0&&v.sourceCount<v.c.records.length;}
}
function createRun(kind,title,stages,other={}){
  if(state.activeRun){notify('Only one Active Run is allowed.');return null;}
  const run={id:uid(kind==='Training'?'train':'build'),kind,title,stages,status:'running',stage:0,progress:0,logs:[`[00:00] ${kind} started`],created:today,...other};
  state.runs.unshift(run);state.activeRun=run;
  timer=setInterval(()=>advanceRun(run),420);
  go(`run/${run.id}`);render();return run;
}
function addLog(run,text){run.logs.push(`[${String(Math.floor(run.progress/10)).padStart(2,'0')}:${String(Math.round(run.progress)%60).padStart(2,'0')}] ${text}`)}
function advanceRun(run){if(!state.activeRun||state.activeRun.id!==run.id){clearInterval(timer);timer=null;return;}
  const previous=run.stage;run.progress=Math.min(100,run.progress+(run.kind==='Training'?2.5:4));run.stage=Math.min(run.stages.length-1,Math.floor(run.progress/(100/run.stages.length)));
  if(run.stage!==previous)addLog(run,`${run.stages[run.stage]}…`);
  if(run.kind==='Training')run.currentMetrics=run.config?.family==='rf'?{f1:0.89,precision:0.9,recall:0.88,accuracy:0.92,rocAuc:0.94}:metrics(run.progress);
  if(run.progress>=100){clearInterval(timer);timer=null;state.activeRun=null;run.status='completed';run.stage=run.stages.length;addLog(run,'Completed · outputs verified and published');
    if(run.kind==='Dataset Build')publishDataset(run);
    if(run.kind==='Training'){run.modelCandidate=true;state.pendingNameRun=run.id;}
  }
  globalRun();if(getRoute()===`run/${run.id}`)runPage(run.id);
}
function runBuild(){const v=computed();if(!v.c.verified||v.sourceCount<2||!v.pos||!v.neg||state.activeRun){notify('Dataset cannot be built with the current selection.');return;}
 const run=createRun('Dataset Build',`Build · ${v.c.name}`,['Validate inputs','Mine negative snippets','Write train / val Splits','Verify and publish Dataset'],{
 collectionId:v.c.id,recordIds:[...state.selectedRecords],requestedPos:v.pos,requestedNeg:v.neg,config:structuredClone(state.config)});
 if(run)addLog(run,`Selected ${v.sourceCount} Source Recordings · ${v.pos} positives · ${v.neg} negatives requested`);
}
function publishDataset(run){
 const d={id:uid('ds'),label:`${coll(run.collectionId)?.name||'Collection'} · Dataset`,collectionId:run.collectionId,recordIds:run.recordIds,pos:run.requestedPos,neg:run.requestedNeg,created:today,config:run.config,demo:true,
 splitCounts:{train:{pos:Math.round(run.requestedPos*run.config.split/100),neg:Math.round(run.requestedNeg*run.config.split/100)},val:{pos:run.requestedPos-Math.round(run.requestedPos*run.config.split/100),neg:run.requestedNeg-Math.round(run.requestedNeg*run.config.split/100)}}};
 state.datasets.unshift(d);run.datasetId=d.id;state.training.datasetId=d.id;
}
function metrics(percent){const x=percent/100;return {trainLoss:1.13*Math.exp(-2.6*x)+.06,valLoss:1.06*Math.exp(-2.15*x)+.14+Math.max(0,x-.73)*.22,f1:.42+.50*(1-Math.exp(-3*x))};}
function cancelRun(id){const run=state.runs.find(r=>r.id===id);if(!run||state.activeRun?.id!==id)return;
 openDialog(`<h2>Cancel ${esc(run.kind)}?</h2><p>Unpublished files will remain staged for controlled cleanup. No Dataset or Model will be published.</p><div class="modal-buttons"><button class="btn" onclick="closeDialog()">Continue Run</button><button class="btn danger" onclick="confirmCancel('${id}')">Cancel Run</button></div>`);
}
function confirmCancel(id){const run=state.runs.find(r=>r.id===id);if(run&&state.activeRun?.id===id){clearInterval(timer);timer=null;run.status='canceled';addLog(run,'Canceled · staged outputs not published');state.activeRun=null;}
 closeDialog();render();}
function runPage(id){const run=state.runs.find(r=>r.id===id);if(!run)return notFound();const active=state.activeRun?.id===id;const completed=run.status==='completed';let actions='';
 if(active)actions=`<button class="btn danger" onclick="cancelRun('${run.id}')">${ico('x',14)} Cancel Run</button>`;
 if(completed&&run.kind==='Dataset Build')actions=`<button class="btn primary" onclick="go('dataset/${run.datasetId}')">Open Dataset ${ico('arrow',14)}</button>`;
 if(completed&&run.kind==='Training')actions=run.modelId?`<button class="btn primary" onclick="go('model/${run.modelId}')">Open Model ${ico('arrow',14)}</button>`:`<button class="btn primary" onclick="nameModel('${run.id}')">Name and save Model ${ico('arrow',14)}</button>`;
 const phase=completed?'Finished':run.status==='canceled'?'Canceled':run.stages[Math.min(run.stage,run.stages.length-1)];const style=completed?'success':run.status==='canceled'?'warn':'';
 const chart=run.kind==='Training'?`<div class="panel panel-inner"><div class="section-title"><h2>${run.config?.family==='rf'?'Validation and feature importance':'Training metrics'}</h2>${tip(run.config?.family==='rf'?'Random Forest produces held-out validation metrics and feature importance, not epoch loss. Values below are simulated.':'Mock training and validation loss, generated for visual review.',true)}</div>${run.config?.family==='rf'?rfChart(run.progress):lossChart(run.progress)}${completed?`<div class="metrics-grid" style="margin-top:16px"><div class="metric-card"><div class="metric">${run.config?.family==='rf'?'0.89':'0.91'}</div><div class="metric-label">val F1</div></div><div class="metric-card"><div class="metric">${run.config?.family==='rf'?'0.90':'0.93'}</div><div class="metric-label">val precision</div></div><div class="metric-card"><div class="metric">${run.config?.family==='rf'?'0.88':'0.89'}</div><div class="metric-label">val recall</div></div></div>`:''}</div>`:'';
 page(`<div class="wide">${bread('Runs','runs',run.id)}${heading('RUN · '+run.kind.toUpperCase(),run.title,`Run ID · ${esc(run.id)} · ${esc(run.created)}`,actions)}<div class="two-col"><div class="stack"><section class="panel panel-inner"><div class="section-title"><h2>${active?'Working locally':completed?'Run completed':'Run canceled'}</h2>${badge(run.status,style)}</div><div class="progress-head"><strong style="font-size:15px">${esc(phase)}</strong><strong style="font-size:20px">${Math.round(run.progress)}%</strong></div><div class="bar" role="progressbar" aria-valuenow="${Math.round(run.progress)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${run.progress}%"></span></div><div class="stage-list">${run.stages.map((stage,i)=>`<div class="stage-item ${run.stage>i?'done':active&&run.stage===i?'current':''}"><span class="stage-num">${run.stage>i?ico('check',12):i+1}</span><span>${esc(stage)}</span></div>`).join('')}</div></section>${chart}<div class="panel panel-inner"><div class="section-title"><h2>Run activity</h2><span class="subtle">Mock log</span></div><div class="activity">${esc(run.logs.join('\n'))}</div></div></div><div class="stack"><div class="panel panel-inner"><div class="section-title"><h2>Output</h2>${tip('A Run is execution history. The Dataset or Model is the reusable scientific artifact. Only verified, published outputs appear in artifact lists.',true)}</div>${run.status==='running'?`<div class="alert">${ico('clock',16)}<div><strong>Not yet published</strong><p>Inputs are read-only. Output is staged until validation completes.</p></div></div>`:run.status==='canceled'?`<div class="alert warning"><div><strong>No published artifact</strong><p>Cancellation does not create a partial Dataset or Model.</p></div></div>`:run.kind==='Dataset Build'?`<div class="alert"><div><strong>Dataset ready</strong><p>Immutable · ${run.requestedPos} targets · ${run.requestedNeg} noise</p></div></div><div class="kv"><span>Dataset ID</span><b class="mono">${esc(run.datasetId)}</b></div><button class="btn primary" style="width:100%;margin-top:16px" onclick="go('dataset/${run.datasetId}')">Open Dataset →</button>`:run.modelId?`<div class="alert"><div><strong>Model saved</strong><p>${esc(model(run.modelId)?.label)}</p></div></div><button class="btn primary" style="margin-top:14px;width:100%" onclick="go('model/${run.modelId}')">Open Model →</button>`:`<div class="alert"><div><strong>Training complete</strong><p>Trained weights are ready. Choose a display name to save the Model.</p></div></div><button class="btn primary" style="margin-top:14px;width:100%" onclick="nameModel('${run.id}')">Name and save Model →</button>`}</div><div class="panel panel-inner"><div class="section-title"><h2>Run details</h2></div><div class="kv"><span>Kind</span><b>${run.kind}</b></div><div class="kv"><span>Status</span><b>${run.status}</b></div>${run.collectionId?`<div class="kv"><span>Collection</span><b>${esc(coll(run.collectionId)?.name||'')}</b></div>`:''}${run.inputDataset?`<div class="kv"><span>Dataset</span><b class="mono">${esc(run.inputDataset)}</b></div>`:''}<div class="kv"><span>Started</span><b>${run.created}</b></div></div></div></div><div class="footnote">This is a timed UI simulation. It does not invoke the native Worker Process or write any files.</div></div>`,'Run · '+run.id);
}
function rfChart(progress){const bars=[['MFCC mean',0.72],['Band energy',0.58],['Spectral entropy',0.43],['MFCC variance',0.35]];return `<div class="rf-feature-chart" role="img" aria-label="Simulated Random Forest feature importance">${bars.map(([name,val])=>`<div class="rf-feature-row"><span>${name}</span><div class="meter"><span style="width:${Math.round(val*progress)}%"></span></div></div>`).join('')}</div><p class="subtle">Illustrative relative importance · available after feature fitting</p>`}
function lossChart(progress){const n=Math.max(2,Math.round(progress/5));const w=620,h=205,left=43,top=16,bottom=35,right=15;const xx=i=>left+(i/(Math.max(1,n-1)))*(w-left-right);const yy=v=>h-bottom-v/1.4*(h-top-bottom);
 const mk=kind=>Array.from({length:n},(_,i)=>`${i?'L':'M'}${xx(i).toFixed(1)},${yy(metrics((i+1)*100/n)[kind]).toFixed(1)}`).join(' ');
 const grids=[0,.35,.7,1.05,1.4].map(y=>`<line x1="${left}" x2="${w-right}" y1="${yy(y)}" y2="${yy(y)}" stroke="#e8eef2"/><text class="chart-label" x="${left-9}" y="${yy(y)+4}" text-anchor="end">${y.toFixed(1)}</text>`).join('');
 return `<div class="chart-legend"><span><i class="legend-dot"></i>train loss</span><span><i class="legend-dot grey"></i>val loss</span></div><div class="chart-shell"><svg viewBox="0 0 ${w} ${h}" class="chart-svg" role="img" aria-label="Simulated train loss and validation loss over epochs">${grids}<path d="${mk('trainLoss')}" stroke="#059669" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" fill="none"/><path d="${mk('valLoss')}" stroke="#94a3b8" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" fill="none"/><text class="chart-label" x="${left}" y="${h-12}">Epoch 1</text><text class="chart-label" x="${w-right}" y="${h-12}" text-anchor="end">Latest epoch</text></svg></div>`;
}
function datasetPage(id){const d=dataset(id);if(!d)return notFound();const c=coll(d.collectionId);const inUse=state.activeRun&&state.activeRun.inputDataset===d.id;const splits=d.splitCounts;
 const actions=`<button class="btn danger" onclick="removeDatasetAsk('${d.id}')" ${inUse?'disabled title="Used by the Active Run"':''}>${ico('trash',14)} Delete</button><button class="btn primary" onclick="openTraining('${d.id}')">Train Model ${ico('arrow',14)}</button>`;
 page(`<div class="wide">${bread('Datasets','datasets',d.id)}${heading('IMMUTABLE DATASET',d.label,`Dataset ID · ${esc(d.id)} · ${esc(d.created)}`,actions)}${stats([['Target Snippets',fmt(d.pos),'positive examples'],['Noise Snippets',fmt(d.neg),'mined background'],['Total Snippets',fmt(d.pos+d.neg),'materialized WAV'],['Source Recordings',String(d.recordIds?.length||c?.records.length||0),'selected for build']])}<div class="two-col"><div class="stack"><div class="panel panel-inner"><div class="section-title"><h2>train / val Splits</h2>${tip('Split assignments are deterministic and grouped by Source Recording. The numbers shown here are illustrative; the native builder checks exact membership and class ratio.',true)}</div>${[['train',splits.train],['val',splits.val]].map(([name,counts])=>`<div style="margin-bottom:18px"><div class="progress-head"><strong>${name}</strong><span class="subtle">${counts.pos+counts.neg} Snippets</span></div><div class="meter split"><span style="width:${100*counts.pos/(counts.pos+counts.neg||1)}%"></span><span style="width:${100*counts.neg/(counts.pos+counts.neg||1)}%"></span></div><div class="subtle" style="margin-top:6px">${counts.pos} target · ${counts.neg} noise</div></div>`).join('')}<div class="alert">${ico('shield',16)}<div><strong>Immutable and reproducible</strong><p>Source metadata, build parameters, splits and per-Snippet provenance are retained.</p></div></div></div><div class="panel panel-inner"><div class="section-title"><h2>Generated Dataset files</h2>${tip('Conceptual on-disk folder under the selected Collection. The prototype does not create these files.',true)}</div><div class="tree"><div><em>.alpaca/datasets/${esc(d.id)}/</em></div><div class="level1">manifest.json</div><div class="level1">entries/*.jsonl</div><div class="level1">snippets/target/*.wav</div><div class="level1">snippets/noise/*.wav</div><div class="level1">splits/train.csv</div><div class="level1">splits/val.csv</div></div></div></div><div class="stack"><div class="panel panel-inner"><h2 class="mini-heading">Dataset provenance</h2><div class="kv"><span>Collection</span><button class="line-button" onclick="openCollection('${d.collectionId}')">${esc(c?.name||'Missing')} →</button></div><div class="kv"><span>Negative amount</span><b>${d.config.mode==='ratio'?d.config.ratio+' / positive':d.config.absolute+' total'}</b></div><div class="kv"><span>Distribution</span><b>${d.config.allocation==='even'?'Even by recording':'Proportional'}</b></div><div class="kv"><span>Split</span><b>${d.config.split} / ${100-d.config.split}</b></div><div class="kv"><span>Class ratio per Split</span><b>${d.config.balance?'Requested':'Not constrained'}</b></div><div class="kv"><span>Exclusion margin</span><b>${d.config.margin} s</b></div><div class="kv"><span>Seed</span><b>${d.config.seed}</b></div></div><div class="panel panel-inner"><h2 class="mini-heading">Next</h2><p class="subtle">Train a classifier with the target/noise Snippets.</p><button class="btn primary" style="width:100%" onclick="openTraining('${d.id}')">Train Model ${ico('arrow',15)}</button></div></div></div></div>`,'Dataset · '+d.id);
}
function datasetsPage(){page(`<div class="wide">${heading('DATA','Datasets','Published, immutable training inputs.',`<button class="btn primary" onclick="go('collections')">${ico('plus',14)} Build Dataset</button>`)}<div class="panel table-wrap"><table class="data-table"><thead><tr><th>Dataset</th><th>Collection</th><th>Snippets</th><th>Created</th><th></th></tr></thead><tbody>${state.datasets.map(d=>`<tr class="clickable" onclick="go('dataset/${d.id}')"><td><strong>${esc(d.label)}</strong><small class="mono">${esc(d.id)}</small></td><td>${esc(coll(d.collectionId)?.name||'')}</td><td>${fmt(d.pos+d.neg)}</td><td>${esc(d.created)}</td><td class="table-link">Open →</td></tr>`).join('')||`<tr><td colspan="5">No Datasets yet. Start from a Collection.</td></tr>`}</tbody></table></div></div>`,'Datasets')}
function removeDatasetAsk(id){const d=dataset(id);if(!d)return;if(state.activeRun?.inputDataset===id||state.activeRun?.datasetId===id){notify('Cannot delete a Dataset used by the Active Run.');return;}
 const usedBy=state.models.filter(m=>m.datasetId===id).length;openDialog(`<h2>Delete Dataset?</h2><p><strong>${esc(d.label)}</strong> will be removed from the Dataset list. Its original Collection stays unchanged.${usedBy?` ${usedBy} already saved Model(s) retain provenance to this Dataset ID.`:''}</p><div class="modal-buttons"><button class="btn" onclick="closeDialog()">Keep Dataset</button><button class="btn danger" onclick="confirmDeleteDataset('${id}')">Delete Dataset</button></div>`);
}
function confirmDeleteDataset(id){state.datasets=state.datasets.filter(d=>d.id!==id);closeDialog();go('datasets');render();notify('Dataset removed in prototype memory.');}
function openTraining(id){if(!dataset(id)){notify('Choose a published Dataset.');return;}state.training.datasetId=id;go('train')}
function trainPage(){const t=state.training,d=dataset(t.datasetId);if(!d)return go('datasets');const c=coll(d.collectionId);const rf=t.family==='rf';
 page(`<div class="wide">${bread('Datasets',`dataset/${d.id}`,'Train Model')}${heading('TRAINING','Train a Model','Choose a classifier. Training uses the selected immutable Dataset.',badge('Runs locally'))}<div class="builder-layout"><div class="stack"><div class="panel panel-inner"><div class="section-title"><div><h2>1 · Dataset</h2><p>Positive and mined-negative WAV Snippets</p></div>${tip('CNN and Random Forest use the same immutable Dataset with train and val Splits.',true)}</div><label class="field"><span class="inline-label">Dataset</span><select onchange="changeDataset(this.value)">${state.datasets.map(ds=>`<option value="${ds.id}" ${ds.id===d.id?'selected':''}>${esc(ds.label)} · ${ds.id}</option>`).join('')}</select></label><div class="summary-box"><div class="summary-nums"><div><strong>${d.pos}</strong><br><small>target</small></div><div><strong>${d.neg}</strong><br><small>noise</small></div><div><strong>${d.pos+d.neg}</strong><br><small>total WAV snippets</small></div></div><div class="meter split"><span style="width:${100*d.pos/(d.pos+d.neg)}%"></span><span style="width:${100*d.neg/(d.pos+d.neg)}%"></span></div></div><div class="kv"><span>Collection</span><b>${esc(c?.name)}</b></div><div class="kv"><span>Splits</span><b>train / val</b></div></div><div class="panel panel-inner"><div class="section-title"><h2>3 · Start Training</h2>${tip('Native Trainer uses a supervised QProcess Worker. Only one Active Run is supported. The browser simulates the Run.',true)}</div><div class="alert">${ico('shield',16)}<div><strong>Dataset stays unchanged</strong><p>${rf?'Extract features, fit a forest, validate and save the classifier.':'Train a neural network and track loss and validation metrics.'}</p></div></div><div class="action-strip"><span class="subtle">${state.activeRun?'Another Run is active.':'One Active Run at a time.'}</span><button class="btn primary large" ${state.activeRun?'disabled':''} onclick="startTraining()">${ico('play',16)} Start Training ${ico('arrow',14)}</button></div></div></div><div class="panel panel-inner"><div class="section-title"><div><h2>2 · Model configuration</h2><p>${rf?'Random Forest · acoustic features':'CNN · spectrogram'}</p></div>${tip('CNN and Random Forest are different model families, selected on the same Training page. RF uses acoustic feature summaries followed by a scikit-learn forest, following the existing alpaca-pipelines algorithm.',true)}</div><div class="setting-block"><label class="field"><span class="inline-label">Model family ${tip('Select an algorithm; both consume a Dataset. Random Forest uses feature extraction, not gradient descent or epochs.',true)}</span><select onchange="setTrain('family',this.value)"><option value="cnn" ${t.family==='cnn'?'selected':''}>CNN · Spectrogram</option><option value="rf" ${rf?'selected':''}>Random Forest · Acoustic features</option></select></label></div>${rf?`<div class="setting-block"><label class="field"><span class="inline-label">Acoustic features ${tip('Uses robust Raven-style acoustic summaries and MFCC (mel-frequency cepstral coefficient) summaries. Feature extraction parameters must be persisted with the Model for future Prediction.',true)}</span><select onchange="setTrain('rfFeatures',this.value)"><option value="robust-mfcc">Robust acoustic + MFCC (reference default)</option></select></label><div class="field-row"><label class="field"><span class="inline-label">Trees ${tip('Number of decision trees in the forest; more trees increase compute cost.',true)}</span><input type="number" min="10" max="5000" step="10" value="${t.trees}" onchange="setTrain('trees',this.value)"></label><label class="field"><span class="inline-label">Min. leaf samples ${tip('Minimum training samples in a decision tree leaf; helps avoid fitting noise.',true)}</span><input type="number" min="1" max="100" step="1" value="${t.leaf}" onchange="setTrain('leaf',this.value)"></label></div><div class="field-row"><label class="field"><span class="inline-label">Maximum tree depth ${tip('0 means no depth cap. The forest stops splitting when other limits apply.',true)}</span><input type="number" min="0" max="200" value="${t.maxDepth}" onchange="setTrain('maxDepth',this.value)"></label><label class="field"><span class="inline-label">Decision threshold ${tip('Classify as target when predicted target probability is at least this value. Validation uses the same threshold.',true)}</span><input type="number" min="0" max="1" step="0.05" value="${t.rfThreshold}" onchange="setTrain('rfThreshold',this.value)"></label></div><p class="subtle">CPU · class weights balanced · seeded forest</p></div>`:`<div class="setting-block"><label class="field"><span class="inline-label">Training device ${tip('CPU or compatible hardware acceleration, subject to native availability checks.',true)}</span><select onchange="setTrain('device',this.value)"><option value="cpu" ${t.device==='cpu'?'selected':''}>CPU</option><option value="mps" ${t.device==='mps'?'selected':''}>Apple GPU · MPS (concept)</option></select></label><div class="field-row"><label class="field"><span class="inline-label">Epochs ${tip('One pass through the Training Split.',true)}</span><input type="number" min="1" max="500" value="${t.epochs}" onchange="setTrain('epochs',this.value)"></label><label class="field"><span class="inline-label">Batch size ${tip('Number of Snippets loaded for each gradient update.',true)}</span><select onchange="setTrain('batch',this.value)">${[8,16,32,64].map(n=>`<option value="${n}" ${t.batch===n?'selected':''}>${n}</option>`).join('')}</select></label></div><label class="field"><span class="inline-label">Learning rate ${tip('Size of each model-parameter update.',true)}</span><select onchange="setTrain('lr',this.value)"><option value="0.001" ${t.lr===0.001?'selected':''}>0.001 · Default</option><option value="0.0001" ${t.lr===0.0001?'selected':''}>0.0001 · Conservative</option><option value="0.01" ${t.lr===0.01?'selected':''}>0.01 · Faster</option></select></label></div>`}<div class="alert"><div><strong>Validation included</strong><p>Use the held-out val Split for F1, precision and recall. ${rf?'Random Forest does not produce epoch-loss curves.':'CNN also reports training and validation loss.'}</p></div></div></div></div></div>`,'Train Model');}
function changeDataset(id){state.training.datasetId=id;trainPage()}
function setTrain(field,value){if(['epochs','batch','lr','trees','leaf','maxDepth','rfThreshold'].includes(field)){value=Number(value);if(!Number.isFinite(value))return;if(field==='epochs')value=Math.max(1,Math.min(500,Math.round(value)));if(field==='trees')value=Math.max(10,Math.min(5000,Math.round(value)));if(field==='leaf')value=Math.max(1,Math.min(100,Math.round(value)));if(field==='maxDepth')value=Math.max(0,Math.min(200,Math.round(value)));if(field==='rfThreshold')value=Math.max(0,Math.min(1,value));}state.training[field]=value;if(field==='family')trainPage();}
function startTraining(){const d=dataset(state.training.datasetId);if(!d||state.activeRun){notify('A published Dataset and an idle Worker are required.');return;}
 createRun('Training',`Train ${state.training.family==='rf'?'Random Forest':'CNN'} · ${d.label}`,state.training.family==='rf'?['Extract acoustic features','Fit Random Forest','Validate predictions','Publish Model and feature metadata']:['Prepare batches','Train model','Validate Model','Publish weights & metrics'],{
 inputDataset:d.id,collectionId:d.collectionId,config:structuredClone(state.training)});
}
function nameModel(id){const run=state.runs.find(r=>r.id===id);if(!run||run.kind!=='Training'||run.status!=='completed'){notify('Complete Training before saving a Model.');return;}
 if(run.modelId){go(`model/${run.modelId}`);return;}
 openDialog(`<h2>Name your Model</h2><p>Choose a readable label. A unique, filename-safe ID is generated from it and retained with the display label in the Model manifest.</p><label class="field"><span class="inline-label">Model display name</span><input type="text" id="model-label" maxlength="80" value="${esc(coll(run.collectionId)?.name||'New')} · classifier" onkeydown="if(event.key==='Enter')saveModel('${run.id}')" /></label><div class="alert"><div><strong>Saved locally</strong><p>Proposed: .alpaca/models/&lt;model-id&gt;/ · both families use stable IDs and readable labels.</p></div></div><div class="modal-buttons"><button class="btn" onclick="closeDialog()">Later</button><button class="btn primary" onclick="saveModel('${id}')">Save Model ${ico('arrow',14)}</button></div>`);setTimeout(()=>$('model-label')?.focus(),0);
}
function saveModel(id){const run=state.runs.find(r=>r.id===id),label=$('model-label')?.value.trim();if(!run||run.modelId||!label)return notify('Enter a nonempty Model name.');
 const m={id:modelIdFor(label),label,datasetId:run.inputDataset,family:run.config.family==='cnn'?'CNN · spectrogram':'Random Forest · acoustic features',created:today,f1:run.config.family==='rf'?0.89:0.91,runId:run.id,demo:true};state.models.unshift(m);run.modelId=m.id;state.pendingNameRun=null;closeDialog();go(`model/${m.id}`);render();
}
function modelPage(id){const m=model(id);if(!m)return notFound();const d=dataset(m.datasetId);const run=state.runs.find(r=>r.id===m.runId);
 page(`<div class="wide">${bread('Models','models',m.label)}${heading('TRAINED MODEL',m.label,`Model ID · ${esc(m.id)} · ${esc(m.created)}`,badge('Ready','success'))}${stats([['Validation F1',m.f1?.toFixed(2)||'—','Illustrative'],['Family',m.family.split(' · ')[0],'Model configuration'],['Source Dataset',esc(m.datasetId),'Immutable input'],['Run',esc(m.runId),'Training history']])}<div class="two-col"><div class="stack"><div class="panel panel-inner"><div class="section-title"><h2>Model details</h2>${tip('The unique Model ID identifies the artifact. Its display label can be human-readable and does not determine file identity.',true)}</div><div class="kv"><span>Display name</span><b>${esc(m.label)}</b></div><div class="kv"><span>Model ID</span><b class="mono">${esc(m.id)}</b></div><div class="kv"><span>Model family</span><b>${esc(m.family)}</b></div><div class="kv"><span>Training Run</span><button class="line-button" onclick="go('run/${esc(m.runId)}')">${esc(m.runId)} →</button></div><div class="kv"><span>Dataset</span>${d?`<button class="line-button" onclick="go('dataset/${d.id}')">${esc(d.id)} →</button>`:`<b class="mono">${esc(m.datasetId)} · deleted</b>`}</div></div><div class="panel panel-inner"><h2 class="mini-heading">Proposed Model files</h2><div class="tree"><div><em>.alpaca/models/${esc(m.id)}/</em></div><div class="level1">manifest.json</div><div class="level1">${m.family.startsWith('Random Forest')?'rf_model.joblib':'model.pt'}</div>${m.family.startsWith('Random Forest')?'<div class="level1">rf_model_metadata.json</div>':''}<div class="level1">metrics.json</div></div></div></div><div class="stack"><div class="panel panel-inner"><div class="section-title"><h2>Use in Prediction</h2>${ico('arrow',17)}</div><p class="subtle">This saved Model will appear in Prediction once the target app supports this model family and its feature-loading contract.</p><a class="btn primary" style="width:100%" href="../prediction-first/index.html" title="Opens the separate Prediction UX prototype">Open Prediction prototype ${ico('arrow',14)}</a><p class="subtle" style="margin:10px 0 0;font-size:11px">The Prediction prototype is separate and does not share this in-memory Model list.</p></div><div class="panel panel-inner"><h2 class="mini-heading">Training metrics</h2><div class="kv"><span>val F1</span><b>${m.f1?.toFixed(2)||'—'}</b></div><div class="kv"><span>val precision</span><b>${m.family.startsWith('Random Forest')?'0.90':'0.93'}</b></div><div class="kv"><span>val recall</span><b>${m.family.startsWith('Random Forest')?'0.88':'0.89'}</b></div>${m.family.startsWith('Random Forest')?'<div class="kv"><span>val ROC-AUC</span><b>0.94</b></div>':''}<button class="btn" style="width:100%;margin-top:15px" onclick="go('run/${run?.id||''}')">Review Training Run →</button></div></div></div></div>`,'Model · '+m.label);
}
function modelsPage(){page(`<div class="wide">${heading('REUSABLE ARTIFACTS','Models','Trained classifiers available to Prediction.',`<button class="btn primary" onclick="go('datasets')">${ico('plus',14)} Train Model</button>`)}<div class="panel table-wrap"><table class="data-table"><thead><tr><th>Model</th><th>Family</th><th>Dataset</th><th>Created</th><th></th></tr></thead><tbody>${state.models.map(m=>`<tr class="clickable" onclick="go('model/${m.id}')"><td><strong>${esc(m.label)}</strong><small class="mono">${esc(m.id)}</small></td><td>${esc(m.family)}</td><td class="mono">${esc(m.datasetId)}</td><td>${esc(m.created)}</td><td class="table-link">Open →</td></tr>`).join('')||'<tr><td colspan="5">No Models saved yet.</td></tr>'}</tbody></table></div></div>`,'Models')}
function runsPage(){page(`<div class="wide">${heading('EXECUTION','Runs','Dataset Build and Training history.',state.activeRun?`<button class="btn primary" onclick="go('run/${state.activeRun.id}')">View Active Run</button>`:'')}<div class="panel table-wrap"><table class="data-table"><thead><tr><th>Run</th><th>Kind</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${state.runs.map(run=>`<tr class="clickable" onclick="go('run/${run.id}')"><td><strong>${esc(run.title)}</strong><small class="mono">${run.id}</small></td><td>${esc(run.kind)}</td><td>${badge(run.status,run.status==='completed'?'success':run.status==='running'?'warn':'')}</td><td>${run.created}</td><td class="table-link">Inspect →</td></tr>`).join('')}</tbody></table></div></div>`,'Runs')}
function wikiPage(){page(`<div class="wide">${heading('WIKI','Selecting a Collection','One folder. WAV files. Timestamps in filenames.',`<button class="btn primary" onclick="go('start')">${ico('folder',14)} Select Collection</button>`)}<div class="two-col"><div class="stack"><div class="panel panel-inner"><div class="section-title"><h2>1 · Create these folders</h2></div><div class="tree wiki-tree"><div><em>Rainforest-dawn/</em> <span class="light">← select this folder</span></div><div class="level1">├─ <em>recordings/</em></div><div class="level2">SITE_001.wav</div><div class="level2">SITE_002.wav</div><div class="level1">└─ <em>positives/</em></div><div class="level2">SITE_001__start-012500ms__end-014900ms__call01.wav</div><div class="level2">SITE_001__start-070000ms__end-071500ms__call02.wav</div><div class="level2">SITE_002__start-001200ms__end-003600ms__call01.wav</div></div><p class="subtle">Use WAV files only. The Trainer creates its own <span class="mono">.alpaca/</span> metadata folder after validation.</p></div><div class="panel panel-inner"><div class="section-title"><h2>2 · Put times in each positive WAV name</h2>${tip('Milliseconds are integers. 1000 ms = 1 s.',true)}</div><div class="code-example">SITE_001__start-012500ms__end-014900ms__call01.wav</div><div class="kv"><span>Source Recording</span><b>SITE_001.wav</b></div><div class="kv"><span>Start</span><b>12.500 s</b></div><div class="kv"><span>End</span><b>14.900 s</b></div><div class="kv"><span>Positive WAV duration</span><b>2.400 s</b></div><p class="subtle">These source-time bounds protect the labeled interval during Negative Mining. Times describe the original recording, not the clip timeline.</p></div></div><div class="stack"><div class="panel panel-inner"><div class="section-title"><h2>3 · What we validate</h2></div><div class="issues"><div class="issue"><strong>Folder layout</strong><small>recordings/ and positives/ are present; WAVs are directly inside.</small></div><div class="issue"><strong>Names</strong><small>Each positive names exactly one complete Source Recording stem.</small></div><div class="issue"><strong>Time intervals</strong><small>Start comes before end; end is inside the original recording.</small></div><div class="issue"><strong>WAV headers</strong><small>Readable audio format; positive duration agrees with filename times.</small></div><div class="issue"><strong>Collisions</strong><small>Duplicate names and duplicate positive intervals are rejected.</small></div></div></div><div class="panel panel-inner"><div class="section-title"><h2>Typical validation messages</h2></div><div class="issues"><div class="issue error"><strong>Unknown Source Recording</strong><small>Change the positive prefix to match an existing WAV name.</small></div><div class="issue error"><strong>Missing timestamps</strong><small>Add __start-…ms and __end-…ms to the positive filename.</small></div><div class="issue error"><strong>Snippet outside recording</strong><small>Correct the end timestamp or choose the right recording.</small></div><div class="issue error"><strong>Duration mismatch</strong><small>Make sure the exported clip length agrees with the named interval.</small></div></div><a class="subtle-link" href="../../../wiki/SELECTING_A_COLLECTION.md">Read the Markdown wiki reference →</a></div></div></div><div class="footnote">A timestamp is a label supplied by the user. Name and header checks cannot prove waveform identity. For that, optional signal verification is needed.</div></div>`,'Wiki · Selecting a Collection')}
function settingsPage(){page(`<div class="wide">${heading('LOCAL FOLDERS','Settings','Trainer metadata and generated artifacts.')}<div class="two-col"><div class="panel panel-inner"><div class="section-title"><h2>Collection folders</h2>${tip('Native Trainer storage contract: the Collection is the selected folder and generated data lives in its app-managed .alpaca/ directory.',true)}</div><div class="kv"><span>Collection</span><b>User-selected folder</b></div><div class="kv"><span>Recordings / positives</span><b>Read-only WAVs</b></div><div class="kv"><span>Collection summary</span><b>.alpaca/collection.json</b></div><div class="kv"><span>Datasets and Models</span><b>.alpaca/ inside Collection</b></div><div class="kv"><span>Binding</span><b>Local Application Settings</b></div></div><div class="panel panel-inner"><h2 class="mini-heading">Native reading plan</h2><div class="issues"><div class="issue"><strong>First selection</strong><small>Async folder listing and one header read per WAV. Save validated records and positive timing references.</small></div><div class="issue"><strong>Reopen</strong><small>Load compact JSON manifest, compare cached size/mtime with filesystem, then recheck changed files only.</small></div><div class="issue"><strong>Large Collections</strong><small>Partition item metadata as JSONL; page the table. Do not read all audio or one enormous JSON array.</small></div><div class="issue"><strong>Scientific safety</strong><small>Validate fingerprints and timestamps again before Dataset Build; no source mutation or WAV copies.</small></div><div class="issue"><strong>Runs</strong><small>QProcess Worker, one Active Run, staged publication, recoverable cancellation.</small></div></div></div></div><div class="footnote">Browser preview can export JSON but cannot automatically write a manifest into the selected directory.</div></div>`,'Settings')}
function notFound(){page(`<div class="narrow">${empty('This page is not available','<button class="btn primary" onclick="go(\'start\')">Select Collection</button>')}</div>`,'Not found')}
function openDialog(html){$('dialog-host').innerHTML=`<div class="modal-overlay" role="presentation" onclick="if(event.target===this)closeDialog()"><div class="modal" role="dialog" aria-modal="true" aria-label="Dialog">${html}</div></div>`;}
function closeDialog(){$('dialog-host').innerHTML=''}
function showAbout(){openDialog(`<h2>BioCall Studio Train</h2><p>Interactive design concept: folder checks use browser WAV header reads; Dataset Build and Training Runs are simulated.</p><div class="alert"><div><strong>Read-only Collection</strong><p>Filename start/end timestamps are validated against WAV header durations; waveform identity is not checked. Browser metadata can be downloaded but is not written to the folder.</p></div></div><div class="modal-buttons"><button class="btn primary" onclick="closeDialog()">Close</button></div>`);}
let toastTimer;
function notify(msg){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=msg;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3500)}
function render(){renderNav();globalRun();const route=getRoute();if(route==='start')home();else if(route==='collections')collectionsPage();else if(route.startsWith('collection/'))collectionPage(route.split('/')[1]);else if(route==='build')buildPage();else if(route==='datasets')datasetsPage();else if(route.startsWith('dataset/'))datasetPage(route.split('/')[1]);else if(route==='train')trainPage();else if(route==='models')modelsPage();else if(route.startsWith('model/'))modelPage(route.split('/')[1]);else if(route==='runs')runsPage();else if(route.startsWith('run/'))runPage(route.split('/')[1]);else if(route==='settings')settingsPage();else if(route==='wiki')wikiPage();else if(route==='scan')showScan();else notFound();}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('screen')?.focus({preventScroll:true});});
render();
